#!/usr/bin/env node

/**
 * Remove orphan thumbnail/preview asset directories.
 *
 * The source of truth for which templates exist is `src/templates/metadata.json`
 * (regenerated by `npm run sketch:meta`). Each template owns an asset directory at
 * `public/assets/images/templates/<engine>/<name>/` holding its thumbnail.webp,
 * thumbnail-2x.webp, preview.webm, preview-md.webm, etc.
 *
 * An "orphan" is an asset directory whose `<engine>/<name>` no longer appears in
 * metadata.json — typically left behind after a sketch is renamed or deleted.
 *
 * Usage:
 *   node scripts/remove-orphan-thumbnails.mjs            # dry run, lists orphans
 *   node scripts/remove-orphan-thumbnails.mjs --delete   # actually remove them
 *   node scripts/remove-orphan-thumbnails.mjs -f         # alias for --delete
 */

import fs from "fs";
import path from "path";
import {
  fileURLToPath
} from "url";

const __dirname = path.dirname( fileURLToPath( import.meta.url ) );
const ROOT_DIR = path.join(
  __dirname,
  ".."
);
const META_PATH = path.join(
  ROOT_DIR,
  "src/templates/metadata.json"
);
const ASSETS_BASE = path.join(
  ROOT_DIR,
  "public/assets/images/templates"
);

const args = new Set( process.argv.slice( 2 ) );
const shouldDelete = args.has( "--delete" ) || args.has( "-f" );

/** `<engine>/<name>` keys for every template that still exists. */
function loadValidKeys() {
  const meta = JSON.parse( fs.readFileSync(
    META_PATH,
    "utf8"
  ) );

  return new Set( meta.map( ( t ) => `${ t.engine }/${ t.name }` ) );
}

/** Recursively count files under a directory, for reporting. */
function countFiles( dir ) {
  let count = 0;

  for ( const entry of fs.readdirSync(
    dir,
    {
      withFileTypes: true
    }
  ) ) {
    count += entry.isDirectory()
      ? countFiles( path.join(
        dir,
        entry.name
      ) )
      : 1;
  }

  return count;
}

/** Find every asset directory with no matching template in metadata.json. */
function findOrphans( validKeys ) {
  const orphans = [];

  if ( !fs.existsSync( ASSETS_BASE ) ) {
    return orphans;
  }

  for ( const engineDir of fs.readdirSync(
    ASSETS_BASE,
    {
      withFileTypes: true
    }
  ) ) {
    if ( !engineDir.isDirectory() ) {
      continue;
    }

    const engine = engineDir.name;
    const enginePath = path.join(
      ASSETS_BASE,
      engine
    );

    for ( const nameDir of fs.readdirSync(
      enginePath,
      {
        withFileTypes: true
      }
    ) ) {
      if ( !nameDir.isDirectory() ) {
        continue;
      }

      const key = `${ engine }/${ nameDir.name }`;

      if ( !validKeys.has( key ) ) {
        const dirPath = path.join(
          enginePath,
          nameDir.name
        );

        orphans.push( {
          key,
          dirPath,
          fileCount: countFiles( dirPath )
        } );
      }
    }
  }

  return orphans;
}

function main() {
  const validKeys = loadValidKeys();
  const orphans = findOrphans( validKeys );

  if ( orphans.length === 0 ) {
    console.log( "No orphan thumbnail/preview directories found." );
    return;
  }

  console.log( `Found ${ orphans.length } orphan asset director${ orphans.length === 1 ? "y" : "ies" }:\n` );

  for ( const {
    key, fileCount
  } of orphans ) {
    console.log( `  ${ key } (${ fileCount } file${ fileCount === 1 ? "" : "s" })` );
  }

  console.log( "" );

  if ( !shouldDelete ) {
    console.log( "Dry run — nothing deleted. Re-run with --delete to remove them." );
    return;
  }

  for ( const {
    dirPath
  } of orphans ) {
    fs.rmSync(
      dirPath,
      {
        recursive: true,
        force: true
      }
    );
  }

  console.log( `Removed ${ orphans.length } orphan asset director${ orphans.length === 1 ? "y" : "ies" }.` );
}

main();
